select
  count(distinct org_id) as orgs_total,
  count(*) as subs_total,
  avg(subs_per_org) as avg_subs_per_org,
  max(subs_per_org) as max_subs_per_org
from (
  select org_id, count(*) as subs_per_org
  from read_parquet('data/subscriptions.parquet')
  group by org_id
)

select
  seq_max,
  count(*) as n_orgs
from (
  select org_id, max(seq_no) as seq_max
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t
group by seq_max
order by seq_max

select
    count(*) as n_orgs,
    avg(n_subs) as avg_subs_per_org,
    sum(case when n_subs > 1 then 1 else 0 end) as orgs_with_multiple_subs
from (
    select org_id, count(*) as n_subs
    from read_parquet('data/subscriptions.parquet')
    group by org_id
) t

select
    min(start_date), max(start_date), max(end_date)
from read_parquet('data/subscriptions.parquet')

-- базовая картина по цепочкам подписок на организацию
select
  count(*) as n_orgs,
  avg(n_subs) as avg_subs_per_org,
  max(n_subs) as max_subs_per_org
from (
  select org_id, count(*) as n_subs
  from read_parquet('data/subscriptions.parquet')
  group by org_id
)
